Import ListNotations.
Open Scope Z_scope.
Set Warnings "-notation-for-abbreviation".
Local Ltac Z.euclidean_division_equations_cleanup ::= idtac.
(* [comment removed for export] *)
Local Ltac acc_hint ::=
  lazymatch goal with
  | |- acc_in ?R (Z_to_bv 64 (Z.shiftr ?a 3 + 2147450880), 1%nat) =>
      match goal with H : rng R (shad ?A) (nshad (?len + ?A' mod 8)) |- _ => constr_eq A A'; apply (acc_shZ R A len a H); lia end
  end.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Section CANSEC1. Context {rc : runConstT}.

Section FWA.
  Variables (SP SPA : Z) (gp tp : word) (F : bvmap 5 word) (fc : bv 32) (RNG : footprint).
  Variables (m0 : amem) (DT WK T nbb maxW minB scl : Z) (sorted : list (option Z)) (js jt : list byte)
    (ncells : nat) (rs0 rv : list Z).
  Variable Q : machine_state -> Prop.
  Hypothesis HJT : length jt = (4 * ncells)%nat.
  Hypothesis HJS : length js = length sorted.
  Hypothesis HLS : length sorted = 256%nat.
  Hypothesis HSYR : forall i v, nth i sorted None = Some v -> 0 <= v < 256.
  Hypothesis PLC : x2placeA RNG m0 SPA DT WK js ncells.
  Hypothesis HT : 1 <= T <= 12.
  Hypothesis HNBB : 2 <= nbb <= 13.
  Hypothesis HWE : 2 <= maxW + 1 <= nbb.
  Hypothesis HTT : nbb - 1 <= T.
  Hypothesis HSCL : scl = nbb - T.
  Hypothesis HMINB : minB = nbb - maxW.
  Hypothesis LRS : length rs0 = 15%nat.
  Hypothesis HRSV : forall w, 1 <= w <= maxW -> 0 <= Znth w rs0 <= Znth (w + 1) rs0 /\ Znth (w + 1) rs0 <= 256.
  Hypothesis LRV : length rv = 156%nat.
  Variable PRV : Z -> Prop.
  Hypothesis HPRV0 : forall w, 1 <= w <= maxW -> PRV w.
  Hypothesis HPRVC : forall c w2, minB <= c <= T - minB -> 1 <= w2 <= maxW -> PRV (rv_idx c w2).
  Hypothesis HRV0 : forall w, 1 <= w <= maxW ->
    0 <= Znth w rv /\ Znth w rv + 2 ^ (T - (nbb - w)) * (Znth (w + 1) rs0 - Znth w rs0) <= 4096.
  Hypothesis HRVC : forall c w2, minB <= c <= T - minB -> 1 <= w2 <= maxW -> 0 <= Znth (rv_idx c w2) rv < 2^31.
